		keyName = "colourPrivate",
		name = "Private",
		description = "Highlight colour for the Private tab",
		position = 3,
		section = "colourSection"
	)
	default Color colourPrivate()
	{
		return new Color(0x3C, 0xFF, 0x7A);
	}

