		position = 2,
		section = "debugSection"
	)
	default boolean logDecisions()
	{
		return false;
	}
}

package com.chattabnotifier;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws the highlight over whichever chat tab buttons have something unread. */
class ChatTabNotifierOverlay extends Overlay
{
	/** How dim a pulse gets at its lowest, so the tab never disappears entirely. */
	private static final float MIN_PULSE = 0.25f;

	/** A solid fill would bury the tab label, so the fill shape is always translucent. */
	private static final float FILL_ALPHA = 0.45f;

	private final Client client;
	private final ChatTabNotifierPlugin plugin;
	private final ChatTabNotifierConfig config;

	@Inject
	ChatTabNotifierOverlay(Client client, ChatTabNotifierPlugin plugin, ChatTabNotifierConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getUnreadTabs().isEmpty())
		{
			return null;
		}

		HighlightShape shape = config.shape();
		int thickness = config.thickness();

		// Java takes the full arc diameter rather than a radius, so a 3 pixel corner is an arc of 6.
		int arc = config.cornerRadius() * 2;

		float strength = config.pulse()
			? pulseFactor(System.currentTimeMillis(), config.pulsePeriod())
			: 1f;

		if (shape == HighlightShape.FILL)
		{
			strength *= FILL_ALPHA;
		}

		graphics.setStroke(new BasicStroke(thickness));

		// On a button only 16 pixels tall an unsmoothed corner reads as a staircase, so round corners
		// get antialiasing. The hint belongs to the shared Graphics2D, so it goes back afterwards.
		Object priorHint = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);

		if (arc > 0)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		}

		try
		{
			for (ChatTab tab : plugin.getUnreadTabs().keySet())
			{
				Rectangle bounds = faceOf(tab);

				if (bounds == null)
				{
					continue;
				}

				graphics.setColor(fade(plugin.colourFor(tab), strength));
				draw(graphics, shape, bounds, thickness, arc);
			}
		}
		finally
		{
			if (arc > 0)
			{
				graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
					priorHint == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : priorHint);
			}
		}

		return null;
	}

	/**
	 * Where to draw a tab's highlight, or null when there is nowhere to draw it.
	 *
	 * <p>The tab's container widget is a few pixels taller than the button face inside it, which
	 * left the highlight hanging below the button. The face is the background sprite, so that is
	 * what gets measured, with the container kept as a fallback in case a client build stops
	 * giving the sprite bounds of its own.
	 */
	private Rectangle faceOf(ChatTab tab)
	{
		Widget container = client.getWidget(tab.getButtonId());

		// The tabs go away with the whole chatbox during cutscenes and the like. The tab stays
		// flagged; there is just nowhere to draw it until the chatbox is back.
		if (container == null || container.isHidden())
		{
			return null;
		}

		Widget face = client.getWidget(tab.getGraphicId());
		Rectangle bounds = face != null && !face.isHidden() ? face.getBounds() : null;

		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			bounds = container.getBounds();
		}

		return bounds != null && bounds.width > 0 && bounds.height > 0 ? bounds : null;
	}

	private static void draw(Graphics2D graphics, HighlightShape shape, Rectangle bounds,
		int thickness, int arc)
	{
		switch (shape)
		{
			case FILL:
				if (arc > 0)
				{
					graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, arc, arc);
				}
				else
				{
					graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
				}

				break;

			case UNDERLINE:
				int barHeight = Math.min(thickness * 2, bounds.height);
				int barY = bounds.y + bounds.height - barHeight;

				if (arc > 0)
				{
					// Clip to the button's own rounded outline so the bar curves in at its ends
					// instead of overhanging the corners. clip() intersects, so the overlay's own
					// clip is kept.
					Shape priorClip = graphics.getClip();
					graphics.clip(new RoundRectangle2D.Float(bounds.x, bounds.y,
						bounds.width, bounds.height, arc, arc));
					graphics.fillRect(bounds.x, barY, bounds.width, barHeight);
					graphics.setClip(priorClip);
				}
				else
				{
					graphics.fillRect(bounds.x, barY, bounds.width, barHeight);
				}

				break;

			case OUTLINE:
			default:
				// A stroke straddles the line it is drawn along, so pull the rectangle in by half of
				// it to keep the whole border inside the button.
				int inset = thickness / 2;

				if (arc > 0)
				{
					graphics.drawRoundRect(bounds.x + inset, bounds.y + inset,
						bounds.width - thickness, bounds.height - thickness, arc, arc);
				}
				else
				{
					graphics.drawRect(bounds.x + inset, bounds.y + inset,
						bounds.width - thickness, bounds.height - thickness);
				}

				break;
		}
	}

	/** A cosine so the pulse eases at both ends rather than snapping between bright and dim. */
	static float pulseFactor(long nowMillis, int periodMillis)
	{
		if (periodMillis <= 0)
		{
			return 1f;
		}

		double phase = (nowMillis % periodMillis) / (double) periodMillis;
		double wave = 0.5 - 0.5 * Math.cos(phase * 2 * Math.PI);

		return (float) (MIN_PULSE + (1 - MIN_PULSE) * wave);
	}

	static Color fade(Color colour, float factor)
	{
		if (factor >= 1f)
		{
			return colour;
		}

		int alpha = Math.max(0, Math.min(255, Math.round(colour.getAlpha() * factor)));

		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha);
	}
}

package com.chattabnotifier;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Notification;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Chat Tab Notifier",
	description = "Highlights the chat tab buttons at the bottom left when a channel has a message you have not read",
	tags = {"chat", "tab", "notify", "highlight", "private", "message", "pm", "clan", "trade", "friends"},
	internalName = "chat-tab-notifier"
)
public class ChatTabNotifierPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(ChatTabNotifierPlugin.class);

	/** Typed as {@code ::chattab}, and only handled while the debugging switch is on. */
	private static final String TEST_COMMAND = "chattab";

	/**
	 * Messages the game files under a channel tab that nobody typed: joins, leaves, and the notices
	 * a clan or friends chat posts about itself.
	 */
	private static final Set<ChatMessageType> CHANNEL_NOTICES = EnumSet.of(
		ChatMessageType.FRIENDSCHATNOTIFICATION,
		ChatMessageType.CLAN_MESSAGE,
		ChatMessageType.CLAN_GUEST_MESSAGE,
		ChatMessageType.CLAN_GIM_MESSAGE,
		ChatMessageType.CLAN_CREATION_INVITATION);

	@Inject
	private Client client;

	@Inject
	private ChatTabNotifierConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ChatTabNotifierOverlay overlay;

	@Inject
	private Notifier notifier;

	/**
	 * Tabs holding something unread, against the wall clock time of their newest message. Written on
	 * the client thread from the event handlers and read on the client thread by the overlay, so no
	 * synchronisation is needed.
	 */
	private final Map<ChatTab, Long> unread = new EnumMap<>(ChatTab.class);

	/** The tab that was open last tick, so switching to a tab can clear it. */
	private ChatTab lastActiveTab;

	@Provides
	ChatTabNotifierConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatTabNotifierConfig.class);
	}

	@Override
	protected void startUp()
	{
		unread.clear();
		lastActiveTab = null;
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		unread.clear();
		lastActiveTab = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			unread.clear();
			lastActiveTab = null;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatTab tab = tabFor(event.getType());

		if (tab == null)
		{
			if (config.logDecisions())
			{
				log.info("{}: not filed under any tab", event.getType());
			}

			return;
		}

		String skipped = reasonToSkip(tab, event);

		if (config.logDecisions())
		{
			log.info("{} on the {} tab: {}", event.getType(), tab.getLabel(),
				skipped == null ? "lighting it up" : "skipped, " + skipped);
		}

		if (skipped != null)
		{
			return;
		}

		boolean firstOfItsKind = unread.put(tab, System.currentTimeMillis()) == null;

		// Only the message that lights a dark tab notifies. A channel mid-conversation would
		// otherwise ping on every line.
		if (firstOfItsKind)
		{
			notifier.notify(notificationFor(tab), describe(tab, event));
		}
	}

	/**
	 * Null when a message should light its tab, otherwise why it should not. Split out from the
	 * handler so the reason can be logged, which is the only way to tell a deliberate skip from a
	 * plugin that is not working.
	 */
	private String reasonToSkip(ChatTab tab, ChatMessage event)
	{
		if (!isEnabled(tab))
		{
			return "the " + tab.getLabel() + " channel is switched off";
		}

		if (config.ignoreSystemMessages() && CHANNEL_NOTICES.contains(event.getType()))
		{
			return "it is a channel notice and those are ignored";
		}

		ChatTab active = activeTab();

		// Nothing to flag if the message landed on the tab already in front of you.
		if (config.suppressActiveTab() && active == tab)
		{
			return "that tab is already open";
		}

		if (config.treatAllTabAsRead() && active == ChatTab.ALL)
		{
			return "the All tab is open and counts as read";
		}

		return null;
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!config.testCommand() || !TEST_COMMAND.equalsIgnoreCase(event.getCommand()))
		{
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		String[] args = event.getArguments();

		// Print what the client says each tab occupies, so the highlight can be lined up against
		// real numbers instead of judged by eye.
		if (args.length > 0 && "bounds".equalsIgnoreCase(args[0]))
		{
			for (ChatTab tab : ChatTab.values())
			{
				String line = tab.getLabel()
					+ " container " + rectOf(client.getWidget(tab.getButtonId()))
					+ ", face " + rectOf(client.getWidget(tab.getGraphicId()));

				log.info("{}", line);
				reply(line);
			}

			return;
		}

		// Light the tabs without going near the chat pipeline, to tell a routing problem from a
		// drawing one.
		if (args.length > 0 && "draw".equalsIgnoreCase(args[0]))
		{
			List<ChatTab> lit = enabledTabs();

			for (ChatTab tab : lit)
			{
				unread.put(tab, System.currentTimeMillis());
			}

			reply(lit.isEmpty()
				? "every channel is switched off, so there is nothing to light"
				: "lit " + describe(lit) + " directly, skipping chat");

			return;
		}

		List<ChatTab> targets;

		if (args.length == 0)
		{
			targets = enabledTabs();

			if (targets.isEmpty())
			{
				reply("every channel is switched off, so nothing would light up");
				return;
			}
		}
		else
		{
			ChatTab named = byName(args[0]);

			if (named == null)
			{
				reply("no channel called '" + args[0]
					+ "'. Try game, public, private, channel, clan, trade, or draw");
				return;
			}

			if (!isEnabled(named))
			{
				reply("the " + named.getLabel()
					+ " channel is switched off, so this message will not light it");
			}

			targets = Collections.singletonList(named);
		}

		for (ChatTab tab : targets)
		{
			client.addChatMessage(sampleType(tab), "Tester", "Chat Tab Notifier test message", null);
		}

		reply("faked a message in " + describe(targets)
			+ ". Nothing left your client and nothing was sent to anyone");
	}

	private List<ChatTab> enabledTabs()
	{
		List<ChatTab> enabled = new ArrayList<>();

		for (ChatTab tab : ChatTab.values())
		{
			if (isEnabled(tab))
			{
				enabled.add(tab);
			}
		}

		return enabled;
	}

	private void reply(String message)
	{
		client.addChatMessage(ChatMessageType.CONSOLE, "", "Chat Tab Notifier: " + message, null);
	}

	private static String rectOf(Widget widget)
	{
		if (widget == null)
		{
			return "missing";
		}

		Rectangle bounds = widget.getBounds();

		if (bounds == null)
		{
			return widget.isHidden() ? "hidden, no bounds" : "no bounds";
		}

		return bounds.width + "x" + bounds.height + " at " + bounds.x + "," + bounds.y
			+ (widget.isHidden() ? " (hidden)" : "");
	}

	private static String describe(List<ChatTab> tabs)
	{
		StringBuilder names = new StringBuilder();

		for (ChatTab tab : tabs)
		{
			if (names.length() > 0)
			{
				names.append(", ");
			}

			names.append(tab.getLabel());
		}

		return names.toString();
	}

	/** A message type that lands on the given tab, for the test command to fake. */
	static ChatMessageType sampleType(ChatTab tab)
	{
		switch (tab)
		{
			case GAME:
				return ChatMessageType.GAMEMESSAGE;

			case PUBLIC:
				return ChatMessageType.PUBLICCHAT;

			case PRIVATE:
				return ChatMessageType.PRIVATECHAT;

			case CHANNEL:
				return ChatMessageType.FRIENDSCHAT;

			case CLAN:
				return ChatMessageType.CLAN_CHAT;

			case TRADE:
				return ChatMessageType.TRADEREQ;

			default:
				return ChatMessageType.GAMEMESSAGE;
		}
	}

	/** Matches a channel the way somebody would type it, nicknames included. */
	static ChatTab byName(String name)
	{
		String wanted = name.trim().toLowerCase(Locale.ROOT);

		switch (wanted)
		{
			case "pm":
			case "pms":
			case "dm":
				return ChatTab.PRIVATE;

			case "fc":
			case "friends":
			case "friendschat":
				return ChatTab.CHANNEL;

			case "cc":
				return ChatTab.CLAN;

			default:
				break;
		}

		for (ChatTab tab : ChatTab.values())
		{
			if (tab.getLabel().toLowerCase(Locale.ROOT).equals(wanted))
			{
				return tab;
			}
		}

		return null;
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		ChatTab active = activeTab();

		// Track this every tick even with nothing unread, otherwise a stale value can match the tab
		// the player switches to later and the switch goes unnoticed.
		if (active != lastActiveTab)
		{
			lastActiveTab = active;

			if (active == ChatTab.ALL && config.treatAllTabAsRead())
			{
				unread.clear();
			}
			else if (active != null)
			{
				unread.remove(active);
			}
		}

		int seconds = config.clearAfter();

		if (seconds > 0 && !unread.isEmpty())
		{
			long cutoff = System.currentTimeMillis() - seconds * 1000L;
			unread.values().removeIf(stamp -> stamp < cutoff);
		}
	}

	/**
	 * Which tab is open. The selected button wears a sprite of its own, which is read first because
	 * it describes itself; {@code CHAT_VIEW} is the fallback for when that sprite set changes.
	 */
	private ChatTab activeTab()
	{
		for (ChatTab tab : ChatTab.values())
		{
			Widget graphic = client.getWidget(tab.getGraphicId());

			if (graphic == null)
			{
				continue;
			}

			int sprite = graphic.getSpriteId();

			if (sprite == Chatbox.SPRITE_SELECTED || sprite == Chatbox.SPRITE_SELECTED_HOVERED)
			{
				return tab;
			}
		}

		return ChatTab.fromChatView(client.getVarcIntValue(Chatbox.VAR_CHAT_VIEW));
	}

	/** The tab a message is filed under, or null for anything that does not belong to one. */
	private static ChatTab tabFor(ChatMessageType type)
	{
		switch (type)
		{
			case PUBLICCHAT:
			case MODCHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
				return ChatTab.PUBLIC;

			case PRIVATECHAT:
			case MODPRIVATECHAT:
				return ChatTab.PRIVATE;

			case FRIENDSCHAT:
			case FRIENDSCHATNOTIFICATION:
				return ChatTab.CHANNEL;

			case CLAN_CHAT:
			case CLAN_MESSAGE:
			case CLAN_GUEST_CHAT:
			case CLAN_GUEST_MESSAGE:
			case CLAN_GIM_CHAT:
			case CLAN_GIM_MESSAGE:
			case CLAN_CREATION_INVITATION:
				return ChatTab.CLAN;

			case TRADEREQ:
			case TRADE:
			case CHALREQ_TRADE:
			case CHALREQ_FRIENDSCHAT:
			case CHALREQ_CLANCHAT:
				return ChatTab.TRADE;

			case GAMEMESSAGE:
			case SPAM:
			case ENGINE:
			case CONSOLE:
			case BROADCAST:
			case WELCOME:
			case LEVELUPMESSAGE:
			case ITEM_EXAMINE:
			case NPC_EXAMINE:
			case OBJECT_EXAMINE:
			case FRIENDNOTIFICATION:
			case IGNORENOTIFICATION:
			case LOGINLOGOUTNOTIFICATION:
			case DIDYOUKNOW:
			case PLAYERRELATED:
			case TENSECTIMEOUT:
			case SNAPSHOTFEEDBACK:
				return ChatTab.GAME;

			default:
				// Dialogue and mesboxes, your own outgoing private message and trade offer, and
				// anything else the client does not put on a tab.
				return null;
		}
	}

	private boolean isEnabled(ChatTab tab)
	{
		switch (tab)
		{
			case GAME:
				return config.notifyGame();

			case PUBLIC:
				return config.notifyPublic();

			case PRIVATE:
				return config.notifyPrivate();

			case CHANNEL:
				return config.notifyChannel();

			case CLAN:
				return config.notifyClan();

			case TRADE:
				return config.notifyTrade();

			default:
				// The All tab shows every channel, so there is nothing it could be unread for.
				return false;
		}
	}

	Color colourFor(ChatTab tab)
	{
		switch (tab)
		{
			case GAME:
				return config.colourGame();

			case PUBLIC:
				return config.colourPublic();

			case PRIVATE:
				return config.colourPrivate();

			case CHANNEL:
				return config.colourChannel();

			case CLAN:
				return config.colourClan();

			case TRADE:
				return config.colourTrade();

			default:
				return Color.WHITE;
		}
	}

	private Notification notificationFor(ChatTab tab)
	{
		switch (tab)
		{
			case GAME:
				return config.notificationGame();

			case PUBLIC:
				return config.notificationPublic();

			case PRIVATE:
				return config.notificationPrivate();

			case CHANNEL:
				return config.notificationChannel();

			case CLAN:
				return config.notificationClan();

			case TRADE:
				return config.notificationTrade();

			default:
				return Notification.OFF;
		}
	}

	private static String describe(ChatTab tab, ChatMessage event)
	{
		String name = event.getName() == null ? "" : Text.removeTags(event.getName()).replace(' ', ' ').trim();

		if (tab == ChatTab.GAME || name.isEmpty())
		{
			return "New " + tab.getLabel().toLowerCase() + " message";
		}

		if (tab == ChatTab.PRIVATE)
		{
			return "Private message from " + name;
		}

		return tab.getLabel() + " message from " + name;
	}

	/** The live map the overlay draws from; both run on the client thread. */
	Map<ChatTab, Long> getUnreadTabs()
	{
		return unread;
	}

	/** For the self check, which has no client to read tabs from. */
	static Map<ChatMessageType, ChatTab> tabMapping()
	{
		Map<ChatMessageType, ChatTab> mapping = new EnumMap<>(ChatMessageType.class);

		for (ChatMessageType type : ChatMessageType.values())
		{
			ChatTab tab = tabFor(type);

			if (tab != null)
			{
				mapping.put(type, tab);
			}
		}

		return Collections.unmodifiableMap(mapping);
	}
}

package com.chattabnotifier;

/**
 * The chatbox interface, sprite and client variable ids this plugin reads.
 *
 * <p>RuneLite names all of these in {@code net.runelite.api.gameval} - {@code InterfaceID.Chatbox},
 * {@code SpriteID.ChatTabButton} and {@code VarClientID.CHAT_VIEW}. Those classes hold nothing but
 * compile time constants, so they are stripped out of the runtime api jar the client ships and
 * cannot be compiled against without pulling the full jar from RuneLite's maven repository. javac
 * inlines the numbers either way, so naming them here produces exactly the same bytecode and keeps
 * the plugin buildable against the jars the client already downloaded.
 */
final class Chatbox
{
	/** Interface group of the chatbox. */
	static final int GROUP = 162;

	/** {@code SpriteID.ChatTabButton.SELECTED}, worn by the background of the open tab. */
	static final int SPRITE_SELECTED = 3053;

	/** {@code SpriteID.ChatTabButton.SELECTED_HOVERED}, the open tab with the mouse over it. */
	static final int SPRITE_SELECTED_HOVERED = 3054;

	/** {@code VarClientID.CHAT_VIEW}, the open tab numbered left to right from zero. */
	static final int VAR_CHAT_VIEW = 41;

	private Chatbox()
	{
	}

	/** Packs a child of the chatbox group into the component id {@code Client.getWidget} takes. */
	static int component(int child)
	{
		return (GROUP << 16) | child;
	}
}

package com.chattabnotifier;

/**
 * How an unread tab is marked.
 *
 * <p>Public on purpose: the config interface hands this back, and RuneLite implements that interface
 * as a dynamic proxy in another package, which cannot reach a package private return type. Hiding it
 * costs an {@code IllegalAccessError} thrown from inside the client's draw loop.
 */
public enum HighlightShape
{
	OUTLINE("Outline"),
	FILL("Filled glow"),
	UNDERLINE("Underline");

	private final String label;

	HighlightShape(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

